// Standarisasi header ke format Master Sheet
const MASTER = {
  'ID Laporan': ['idlaporan','id','idtransaksi','idreport','reportid','nolaporan','kodelaporan','nomorlaporan'],
  'Tanggal Transaksi': ['tanggaltransaksi','tanggal','tgl','tgltransaksi','date','transactiondate','tanggallaporan'],
  'Nama Karyawan': ['namakaryawan','karyawan','namasales','sales','salesperson','employee','pegawai','petugas'],
  'Nama Produk': ['namaproduk','produk','product','productname','barang','namabarang','item'],
  'Jumlah Penjualan': ['jumlahpenjualan','jumlah','qty','quantity','jumlahterjual','terjual','unitterjual','unit'],
  'Pendapatan': ['pendapatan','revenue','omzet','total','totalharga','totalpendapatan','income','nominal']
};

const norm = s => String(s).toLowerCase().replace(/[^a-z0-9]/g, '').replace(/rp$/, '');
const lookup = {};
for (const [master, aliases] of Object.entries(MASTER)) {
  lookup[norm(master)] = master;
  aliases.forEach(a => lookup[a] = master);
}

const out = [];
for (const item of $input.all()) {
  const row = {};
  for (const [key, value] of Object.entries(item.json)) {
    const target = lookup[norm(key)];
    if (target) row[target] = (typeof value === 'string') ? value.trim() : value;
    else if (key === 'Sumber') row['Sumber'] = value;   // kolom penanda asal sheet
  }
  // Pastikan semua kolom Master Sheet selalu ada
  for (const master of Object.keys(MASTER)) {
    if (row[master] === undefined) row[master] = '';
  }
  // Lewati baris kosong total
  if (!row['ID Laporan'] && !row['Pendapatan'] && !row['Jumlah Penjualan']) continue;
  out.push({ json: row });
}
return out;

// Generate Laporan: agregasi data konsolidasi
const FILTER_BULAN = true; // ubah ke false jika ingin menghitung SEMUA data (misal saat testing)

const toNumber = v => {
  if (typeof v === 'number') return v;
  if (v === undefined || v === null || v === '') return 0;
  // "Rp 1.500.000" -> 1500000 ; "1.500,50" -> 1500.5
  let s = String(v).replace(/[^0-9.,-]/g, '');
  if (s.includes(',') && s.includes('.')) s = s.replace(/\./g, '').replace(',', '.');
  else if (s.includes(',')) s = s.replace(',', '.');
  else if ((s.match(/\./g) || []).length > 1) s = s.replace(/\./g, '');
  const n = parseFloat(s);
  return isNaN(n) ? 0 : n;
};

const parseDate = v => {
  if (!v) return null;
  if (v instanceof Date) return v;
  if (typeof v === 'number') return new Date(Math.round((v - 25569) * 86400 * 1000)); // serial Google Sheets/Excel
  const s = String(v).trim();
  let m = s.match(/^(\d{4})-(\d{1,2})-(\d{1,2})/);
  if (m) return new Date(+m[1], +m[2] - 1, +m[3]);
  m = s.match(/^(\d{1,2})[\/\-](\d{1,2})[\/\-](\d{4})/);
  if (m) return new Date(+m[3], +m[2] - 1, +m[1]);
  const d = new Date(s);
  return isNaN(d) ? null : d;
};

const rupiah = n => 'Rp ' + Math.round(n).toLocaleString('id-ID');
const bulanNama = ['Januari','Februari','Maret','April','Mei','Juni','Juli','Agustus','September','Oktober','November','Desember'];

// Tentukan periode: jika dijalankan tanggal 1 -> laporan bulan sebelumnya, selain itu bulan berjalan
const now = new Date();
let year = now.getFullYear();
let month = now.getMonth();
if (now.getDate() === 1) {
  month -= 1;
  if (month < 0) { month = 11; year -= 1; }
}

let rows = $input.all().map(i => i.json);
if (FILTER_BULAN) {
  rows = rows.filter(r => {
    const d = parseDate(r['Tanggal Transaksi']);
    return d && d.getFullYear() === year && d.getMonth() === month;
  });
}

let totalPenjualan = 0, totalPendapatan = 0;
const perSumber = {};
const hariAktif = new Set();

for (const r of rows) {
  const qty = toNumber(r['Jumlah Penjualan']);
  const rev = toNumber(r['Pendapatan']);
  totalPenjualan += qty;
  totalPendapatan += rev;
  const src = r['Sumber'] || 'Tidak diketahui';
  perSumber[src] = perSumber[src] || { transaksi: 0, pendapatan: 0 };
  perSumber[src].transaksi += 1;
  perSumber[src].pendapatan += rev;
  const d = parseDate(r['Tanggal Transaksi']);
  if (d) hariAktif.add(d.toDateString());
}

const jumlahTransaksi = rows.length;
const rataPendapatanPerTransaksi = jumlahTransaksi ? totalPendapatan / jumlahTransaksi : 0;
const rataPenjualanPerTransaksi = jumlahTransaksi ? totalPenjualan / jumlahTransaksi : 0;
const rataPendapatanPerHari = hariAktif.size ? totalPendapatan / hariAktif.size : 0;

const periode = FILTER_BULAN ? `${bulanNama[month]} ${year}` : 'Semua periode';

const rincianSumber = Object.entries(perSumber)
  .map(([k, v]) => `  - ${k}: ${v.transaksi} transaksi, ${rupiah(v.pendapatan)}`)
  .join('\n');

const pesan =
`📊 LAPORAN PERFORMA PENJUALAN
Periode: ${periode}

• Total Sales (unit terjual): ${totalPenjualan.toLocaleString('id-ID')}
• Total Revenue: ${rupiah(totalPendapatan)}
• Jumlah Transaksi: ${jumlahTransaksi}

Rata-rata performa:
• Pendapatan per transaksi: ${rupiah(rataPendapatanPerTransaksi)}
• Unit per transaksi: ${rataPenjualanPerTransaksi.toFixed(2)}
• Pendapatan per hari aktif: ${rupiah(rataPendapatanPerHari)}

Rincian per sumber:
${rincianSumber || '  - (tidak ada data)'}

Dikirim otomatis oleh n8n.`;

return [{
  json: {
    periode,
    totalPenjualan,
    totalPendapatan,
    jumlahTransaksi,
    rataPendapatanPerTransaksi,
    rataPenjualanPerTransaksi,
    rataPendapatanPerHari,
    perSumber,
    pesan,
    pesanHtml: pesan.replace(/\n/g, '<br>')
  }
}];
